"""Record agreement declarations for one saved study, outside purchase execution."""
CSS='''
#po-agreement{margin-top:14px;border-top:1px solid #d2dfed;padding-top:12px}#po-agreement>summary{font-size:14px;font-weight:650;cursor:pointer}#po-agreement .fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}#po-agreement label{display:block;font-size:13px;margin:10px 0}#po-agreement input:not([type=checkbox]){display:block;width:100%;box-sizing:border-box;padding:9px;border:1px solid #b8cce3;border-radius:6px;font:inherit;margin-top:5px}#po-agreement .scope{font-size:12px;color:#536b85}#po-agreement ul{font-size:13px;line-height:1.5}@media(max-width:600px){#po-agreement .fields{grid-template-columns:1fr}}
'''
JS=r'''
(function(){let sequence=0;const previous=renderFinancialContext;renderFinancialContext=function(report){previous(report);const current=++sequence,agreement=report.purchase_agreement||{status:'NOT_DECLARED',revision:0,events:[]},active=agreement.status==='DECLARED_UNVERIFIED';$('po-agreement')?.remove();const box=document.createElement('details');box.id='po-agreement';for(const type of ['input','change'])box.addEventListener(type,event=>event.stopPropagation());const summary=document.createElement('summary');summary.textContent='Acuerdo con el proveedor · '+(active?'Anotado, sin verificar':agreement.status==='RETRACTED'?'Dejado sin efecto':'Pendiente');box.append(summary);const note=document.createElement('p');note.textContent='Registra un acuerdo de las condiciones y cuotas de '+report.proposal.reference+'. Si han cambiado, crea y guarda primero un borrador.';box.append(note);
 if(agreement.events.length){const history=document.createElement('details'),heading=document.createElement('summary'),list=document.createElement('ul');heading.textContent='Ver historial de declaraciones';history.append(heading);for(const event of agreement.events){const li=document.createElement('li');li.textContent=(event.action==='DECLARE'?'Acuerdo anotado':'Dejado sin efecto')+' · '+stockDate(event.agreement_date)+' · '+event.actor+' · '+event.source_reference+(event.reason?' · '+event.reason:'');list.append(li)}history.append(list);box.append(history)}
 const fields=document.createElement('div');fields.className='fields';const inputs={};for(const [key,label,type] of [['actor','Responsable que lo declara','text'],['agreement_date',active?'Fecha de la retirada':'Fecha del acuerdo','date'],['source_reference',active?'Referencia de la retirada':'Referencia del soporte del acuerdo','text']]){const wrapper=document.createElement('label'),input=document.createElement('input');wrapper.textContent=label;input.id='po-agreement-'+key;input.type=type;input.required=true;input.maxLength=256;wrapper.append(input);fields.append(wrapper);inputs[key]=input}box.append(fields);
 if(active){const label=document.createElement('label'),input=document.createElement('input');label.textContent='Motivo de dejarlo sin efecto';input.id='po-agreement-reason';input.required=true;input.maxLength=256;label.append(input);box.append(label);inputs.reason=input}
 const label=document.createElement('label'),ack=document.createElement('input');ack.type='checkbox';ack.id='po-agreement-ack';ack.required=true;label.append(ack,document.createTextNode(active?' Declaro que esta anotación queda sin efecto; su historial se conserva.':' Declaro que el soporte corresponde a estas condiciones y cuotas. La anotación no verifica el soporte ni autoriza la compra.'));box.append(label);const action=document.createElement('button');action.type='button';action.id='po-agreement-save';action.textContent=active?'Dejar declaración sin efecto':'Registrar acuerdo declarado';const notice=document.createElement('p');notice.id='po-agreement-notice';notice.setAttribute('role','status');box.append(action,notice);const scope=document.createElement('p');scope.className='scope';scope.textContent='Anotación local · No envía pedidos, no modifica la propuesta y no registra pagos.';box.append(scope);($('po-guide-agreement-content')||$('po-study-state')).append(box);
 action.onclick=async()=>{for(const input of [...Object.values(inputs),ack])if(!input.reportValidity())return;action.disabled=true;notice.textContent='Guardando declaración…';try{const data={dataset_id:report.dataset_id,proposal_id:report.proposal_id,review_id:report.review_id,revision:agreement.revision,action:active?'RETRACT':'DECLARE',acknowledge:ack.checked};for(const [key,input] of Object.entries(inputs))data[key]=input.value.trim();await api('/api/purchases/agreement',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify(data)});if(current!==sequence||$('dataset').value!==report.dataset_id||document.body.dataset.purchaseMode!=='saved'||printableReview?.proposal_id!==report.proposal_id)return;await reviewSaved(report.proposal_id,action)}catch(error){notice.textContent=error.message}finally{action.disabled=false}};
};})();
'''
